fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let d=Path::new(D);let full=r.join("performance-analysis.json").exists();let stage=if full{"performance"}else{"screen"};let a=read(r.join(format!("{stage}-analysis.json")));let protocol=read(r.join(stage).join("protocol.json"));for(p,h)in protocol["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap(),"closing pin {p}");}let manifest=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}assert_eq!(hash("/tmp/zopro-grouping-module/native/candidate-sdk"),"03e1260e89068c2bec37a2471c34e93628a9f081903e1b7eee9cab9c306aaf3d");assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),109);assert_eq!(read(r.join("codegen-audit.json"))["generic_dot_helper_symbol_absent"],true);
 let inventory=read(r.join("proof-inventory.json"));let mut seen=BTreeSet::new();for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());if p.ends_with(".proof"){assert_eq!(fs::metadata(p).unwrap().len(),164);assert!(seen.insert(h.as_str().unwrap()));}}assert_eq!(seen.len(),a["independent_exports"].as_u64().unwrap()as usize);assert_eq!(inventory.as_object().unwrap().len(),seen.len()*2);
 let audit=json!({"status":if full{"full verified SDK study complete; review pending"}else{"short verified SDK screen closed"},"native_core_tests":109,"new_core_tests":0,"existing_full_buffer_comparisons":384,"raw_tests":2,"cubic_tests":6,"field_source_and_qualification_inherited_unchanged":true,"source_originals":170,"production_sources_checked_unchanged":170,"unchanged_candidate_originals":169,"new_module":false,"generic_helper_absent_in_actual_ELF":true,"fresh_control_reused_unchanged":true,"new_control_build_claimed":false,"closing_pins_checked":protocol["pins"].as_object().unwrap().len(),"SDK_requests":a["sdk_requests"],"independent_gnark_exports":a["independent_exports"],"proof_public_members":inventory.as_object().unwrap().len(),"next_prior_count":a["next_prior_count"],"full_stage_executed":full,"new_profiles":if full{3}else{0},"screen_repeated":false,"candidate_retained":true,"adopted":false,"goal_achieved":false,"next_action":if full{"Assess every full gate and current compiler/resource/profile evidence against the original objective before adoption. Small reliable gains have no floor; passing this trial alone cannot establish all-eight10x."}else{"Retain both scalar fusion implementations and all controls. Do not rerun this unchanged failed screen or keep tuning generic helper boundaries if direct fusion is also unqualified. Choose the next mechanism from actual request-critical work and current MSM arithmetic dependencies; no blind inline/width/pool sweep."}});save(r.join("closeout.json"),&audit);
 let primary=&a["cases"]["1x2-w32"];let pa=primary["pairs"]["direct/accepted"]["geometric_ratio"].as_f64().unwrap();let pf=primary["pairs"]["direct/fresh"]["geometric_ratio"].as_f64().unwrap();let mut md=format!("# Direct width-three Poseidon fusion\n\nPrimary32 direct/accepted and direct/fresh paired ratios are **{pa:.6} / {pf:.6}**. Screen advances: **{}**; full gate passes: **{}**. Production is unchanged and the candidate is retained. No minimum positive-gain threshold is used.\n\nThe width-three dense matrix now forms each row with the existing fused two-product field operation plus its third ordinary product. The partial-round rest uses one fused pair directly. This removes the [previous generic helper](../2026-10-27-poseidon-fused-dot/README.md), its slice loop and its zero accumulator. It is a distinct source version; the preceding failed screen is not repeated or reclassified.\n\nOnly `solver/sparse_poseidon.rs` changes: two explicit width-three formula branches. Reversing those changes recovers every original byte; the other 169 originals remain identical. Other widths retain the original loops. All S-boxes, constants, prefixes, recognizer checks, original wire/slot/A/B/C writes, scheduling and dependency ordering remain unchanged. There is no new module, field primitive, runtime experiment flag, table, copied plan, heap workspace, pool, image-format or resource-policy change.\n\n## Verified SDK comparison\n\nThe controls are the exact historical accepted SDK and the exact fresh baseline executable built in the preceding experiment. Its original 170-source baseline, linked libraries, consumer and binary pins are rechecked; this report claims no new baseline build. Its earlier all-nine-circuit independent proof validation is already in the prior 6,982-proof ledger and is not counted again. Only the direct candidate is rebuilt with the same compiler, native flags, fat LTO, one code-generation unit and standard SDK driver.\n\nFresh blinded proving, witness construction, self-verification and serialization are timed together; loading and three primes are excluded. Process medians pair within rotated/reversed fresh-process blocks. CPU includes scheduling; lifetime RSS includes loading/primes and is not minimum RAM.\n\n|Case|Accepted ms|Fresh ms|Direct ms|Direct/accepted|Direct/fresh|Saving vs fresh µs|Wins vs fresh|Direct RSS MiB|Direct CPU ms/request|\n|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|\n",read(r.join("screen-analysis.json"))["screen_advances_to_full"],a["full_gate_passed"]);
 for(name,c)in a["cases"].as_object().unwrap(){let m=&c["modes"];let p=&c["pairs"];writeln!(md,"|{name}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|{:.3}|{}|{:.2}|{:.3}|",m["accepted"]["ms"].as_f64().unwrap(),m["fresh"]["ms"].as_f64().unwrap(),m["direct"]["ms"].as_f64().unwrap(),p["direct/accepted"]["geometric_ratio"].as_f64().unwrap(),p["direct/fresh"]["geometric_ratio"].as_f64().unwrap(),p["direct/fresh"]["saving_us"].as_f64().unwrap(),p["direct/fresh"]["wins"],m["direct"]["maxrss_mib"].as_f64().unwrap(),m["direct"]["cpu_ms_per_request"].as_f64().unwrap()).unwrap();}
 md.push_str("\nThe short screen has three blocks of accepted/fresh/direct at primary16 and primary32, with 17 timed requests plus three primes per process. Declared gates require fresh/accepted calibration within factor 1.05 in each block and factor 1.03 for paired medians; primary32 improvement against both controls in at least two of three blocks; and both cases within 2% nonregression against both controls. All failures and block ratios remain retained, without exclusions, threshold relaxation or successful repeats.\n\n");for(key,title)in [("calibration_failures","Calibration"),("primary_failures","Primary improvement"),("regressions","Nonregression")]{writeln!(md,"{title} failures: `{}`.\n",a[key]).unwrap();}
 if full{md.push_str("The full stage uses seven blocks over all nine circuits at32workers plus primary16, then three warm-gated199Hz profiles after all latency captures. Its full rule additionally requires original-eight paired geometric improvement/tie against both controls, every-case nonregression, and primary32 improvement with at least four of seven winning blocks.\n\n|Shape|Direct ms|M5 CPU ms|CPU/direct|M5 Metal ms|Metal/direct|\n|---|---:|---:|---:|---:|---:|\n");for c in a["cases"].as_object().unwrap().values().filter(|c|c["workers"]==32){let ms=c["modes"]["direct"]["ms"].as_f64().unwrap();if let(Some(cpu),Some(metal))=(c["reference"]["cpu_ms"].as_f64(),c["reference"]["metal_ms"].as_f64()){writeln!(md,"|{}|{ms:.6}|{cpu:.0}|{:.3}|{metal:.0}|{:.3}|",c["shape"].as_str().unwrap(),cpu/ms,metal/ms).unwrap();}else{writeln!(md,"|{}|{ms:.6}|—|—|—|—|",c["shape"].as_str().unwrap()).unwrap();}}}else{assert!(!r.join("performance").exists());md.push_str("The full stage and cycle profiles did not run. The [last complete all-shape SDK matrix](../2026-10-26-pairing-x-chain-sdk/README.md) retains all supplied M5 CPU/Metal comparisons and remains authoritative outside this short screen. No arithmetic-only timing was used for selection.\n");}
 md.push_str("\n## Validation and limits\n\nAll 109 native core tests, two raw tests, six cubic tests, generator and portable/no-IFMA consumer checks pass. The existing independent all-width symbolic fixture covers 384 complete-buffer comparisons, 48 malformed-recognition rejections and 48 tail-error comparisons, including width-three, reversed operands and present/omitted C. No duplicate helper tests were added. Field source and qualification are inherited unchanged; no new field-suite run is claimed.\n\nThe actual linked direct SDK contains no generic `sparse_poseidon::dot::dot` helper symbol; the source has two explicit fused call sites. [Code-generation audit](artifacts/codegen-audit.json) retains that check. Removing the helper does not by itself establish a causal latency gain. No dynamic call count is claimed.\n\nCandidate preflight covers all nine circuits at four workers, one timed request plus three primes: 36 SDK requests and nine fresh independently verified exports. Subsequent measured exports also pass independent Gnark verification, 164-byte length, pinned public-input binding and freshness against all prior identities. Internal primes are not counted as exported proof identities.\n\n");writeln!(md,"Total **{} SDK requests**, **{} distinct independently verified exports**, **{} proof/public members**; next proof-ledger count **{}**. Full stage: **{}**; new cycle profiles: **{}**. All 170 production files and accepted SDK are unchanged. The original all-eight CPU10× objective remains active and unmet; this report adopts no change.\n",a["sdk_requests"],a["independent_exports"],inventory.as_object().unwrap().len(),a["next_prior_count"],full,if full{3}else{0}).unwrap();md.push_str("No owned helper, build, hash or archive overlaps SDK timing/profile captures. Closing checks rehash all pinned sources, libraries, binaries, tools and proof members. No new AWS/Aeglos, phone, TEE, giant-circuit, swap, minimum-RAM, memory-pressure, concurrent-prover or throughput qualification is claimed.\n\n");for(name,p)in [("reused fresh",r.join("fresh-control-artifacts.json")),("direct",r.join("native/direct/artifacts.json"))]{let b=read(p);writeln!(md,"{name} executable: `{}`; SHA-256 `{}`.\n",b["binary"].as_str().unwrap(),b["binary_sha256"].as_str().unwrap()).unwrap();}md.push_str("[Design](artifacts/design.md), [implementation audit](artifacts/implementation-audit.json), [screen analysis](artifacts/screen-analysis.json), [native tests](artifacts/native/core/tests.json), [proof inventory](artifacts/proof-inventory.json), [artifact hashes](artifact-index.json).\n");fs::create_dir_all(d).unwrap();fs::write(d.join("README.md"),md).unwrap();fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",r.join("accepted-source-manifest.json")).unwrap();fs::copy("/home/ubuntu/src/zk-tools/zopro/crates/zopro-core/src/solver/sparse_poseidon.rs",r.join("accepted-sparse-poseidon.rs")).unwrap();let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);for(rel,h)in &index{assert_eq!(&hash(d.join("artifacts").join(rel)),h);}for(p,h)in inventory.as_object().unwrap(){let rel=Path::new(p).strip_prefix(r).unwrap();assert_eq!(hash(d.join("artifacts").join(rel)),h.as_str().unwrap());}save(d.join("artifact-index.json"),&json!(index));println!("{}artifact hashes;{}proof/public members checked;nextprior{}",index.len(),inventory.as_object().unwrap().len(),a["next_prior_count"]);}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){let mut paths:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();paths.sort();for p in paths{let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();if s.starts_with("target-"){continue;}if p.is_dir(){archive(root,&p,dest,index);continue;}if s.starts_with("candidate/")&&s!="candidate/crates/zopro-core/src/solver/sparse_poseidon.rs"{continue;}if !["json","jsonl","rs","md","txt","log","proof","public"].iter().any(|x|p.extension().is_some_and(|e|e==*x)){continue;}let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(s,h);}}
